package com.p2p.escrow.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="trade_orders") public class TradeOrder { @Id public UUID id=UUID.randomUUID(); @Column(name="maker_id") public UUID makerId; @Enumerated(EnumType.STRING) public Enums.Side side; public String asset; @Column(name="crypto_amount") public BigDecimal cryptoAmount; @Column(name="fiat_amount") public BigDecimal fiatAmount; @Column(name="fiat_currency") public String fiatCurrency; @Column(name="payment_methods") public String paymentMethods; @Enumerated(EnumType.STRING) public Enums.OrderStatus status=Enums.OrderStatus.OPEN; @Column(name="taker_id") public UUID takerId; @Version public long version; @Column(name="created_at") public Instant createdAt=Instant.now(); }
